import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.Cs5aHXsR.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"woodpecker-ci-mcp","text":"Your CI, in the conversation","tagline":"MCP server for Woodpecker CI — read repositories, pipelines and logs, and drive builds, secrets and crons","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/woodpecker-ci-mcp"}]},"features":[{"title":"Answers why the build failed","details":"get_step_logs returns the output of the step that broke, decoded from the base64 chunks the API actually sends, in line order, with its exit code — and from the end of the log by default, because that is where the error is."},{"title":"The whole API, not the read half","details":"Restart a pipeline, cancel a runaway, approve a blocked one, rotate a secret, fix a cron, drain an agent. 71 tools against Woodpecker 3.18.0 — the point of an MCP server for a CI system is doing something about what it tells you."},{"title":"Only the tools you want","details":"WOODPECKER_READ_ONLY=true registers the 34 read tools and nothing else. WOODPECKER_ALLOW_TOOLS cuts finer — essential for a curated eight, your own comma-separated list, or a whole family with list_* — and WOODPECKER_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Safe by default","details":"Twenty-three irreversible operations ask a person first, through MCP elicitation — a dialog the model cannot answer on its behalf, falling back to a server-issued token bound to the exact arguments where the client cannot show one. Agent tokens are redacted on read, build logs are marked untrusted, and read-only mode simply does not register the write tools."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380634000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 300`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`How woodpecker-ci-mcp connects an MCP client to Woodpecker CI`),t(`desc`,{id:`arch-desc`},`An MCP client talks to woodpecker-ci-mcp over stdio. The server calls the Woodpecker CI API over HTTPS. The build agents pull work from the Woodpecker server directly, on a path this server is not on.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`70`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`103`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`123`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`272`,y:`60`,width:`186`,height:`100`,rx:`10`}),t(`text`,{class:`label-title`,x:`365`,y:`93`,"text-anchor":`middle`},`woodpecker-ci-mcp`),t(`text`,{class:`label-muted`,x:`365`,y:`113`,"text-anchor":`middle`},`71 tools, 8 essential`),t(`text`,{class:`label-muted`,x:`365`,y:`133`,"text-anchor":`middle`},`asks a person`),t(`rect`,{class:`node`,x:`550`,y:`70`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`103`,"text-anchor":`middle`},`Woodpecker`),t(`text`,{class:`label-muted`,x:`625`,y:`123`,"text-anchor":`middle`},`server`),t(`path`,{class:`edge-accent`,d:`M180,110 L264,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`222`,y:`98`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M458,110 L542,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`500`,y:`98`,"text-anchor":`middle`},`HTTPS`),t(`text`,{class:`label-muted`,x:`500`,y:`130`,"text-anchor":`middle`},`/api`),t(`rect`,{class:`node`,x:`520`,y:`215`,width:`180`,height:`62`,rx:`10`}),t(`text`,{class:`label-title`,x:`610`,y:`242`,"text-anchor":`middle`},`Build agents`),t(`text`,{class:`label-muted`,x:`610`,y:`261`,"text-anchor":`middle`},`run your pipelines`),t(`path`,{class:`edge edge-dashed`,d:`M625,213 L625,158`,"marker-end":`url(#arch-arrow)`}),t(`text`,{class:`label-mono`,x:`655`,y:`190`,"text-anchor":`start`},`pull`)]),t(`figcaption`,null,`The server reads and drives the Woodpecker server. The agents that actually run your pipelines pull their work directly from it, on a path this server never touches — which is why an agent token is a credential worth redacting.`)],-1),r(`<h2 id="_71-tools-or-eight" tabindex="-1">71 tools, or eight <a class="header-anchor" href="#_71-tools-or-eight" aria-label="Permalink to “71 tools, or eight”">​</a></h2><p>The tool list is not fixed. <code>WOODPECKER_ALLOW_TOOLS=essential</code> narrows it to the eight that cover the job end to end — find the repository, read its pipelines and logs, run one again — and a name that matches nothing stops the server instead of quietly leaving a tool out of <code>tools/list</code>.</p><p><img src="/demo.gif" alt="Finding a failed pipeline, reading the failing step&#39;s log, and restarting it" width="1200" height="420"></p><p>Recorded from <code>docs/demo.tape</code> against a throwaway instance. The server starts without any configuration at all, so registries and inspectors can introspect it; every call then fails with setup instructions instead of reaching the API.</p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start woodpecker-ci-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,7)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};